WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_ga_even'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '均匀分组', 'kp-pc-ga-even', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "隔板法（均匀分组）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "将 n 个【完全相同】的元素分给 m 个对象，每人至少分 1 个。方案数 = C(n-1, m-1)。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "极高频题型！“将 10 个【一模一样】的苹果，分给 3 个小朋友，每个人至少分 1 个，有几种分法？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把 10 个苹果排成一排，中间有 9 个缝隙。因为要分成 3 份，只需要拿 2 块隔板，插进这 9 个缝隙中即可！"}]}, {"type": "katexBlock", "attrs": {"content": "N = C_{n-1}^{m-1} = C_9^2 = \\frac{9 \\times 8}{2 \\times 1} = 36"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "元素不同不能用隔板：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果苹果是不同颜色的，绝不能用隔板法！隔板法的前提必须是“一模一样、无法区分”的元素！"}]}]}]}$$ AS jsonb), NULL, '均匀分组的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "均匀分组"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_ga_even", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
